from pathlib import Path
from datetime import date, datetime
import json
import sys
from lire_reporting_xlsx import lire_reporting

ROOT=Path(__file__).parent; XLSX=ROOT/'Base_Donnees_GIL_Reporting_Equipe_Corrige.xlsx'; OUT=ROOT/'dashboard_gil_sprint.html'
headers, lignes = lire_reporting(XLSX); records=[]
for vals in lignes:
    r={headers[i]:vals[i] for i in range(len(headers)) if headers[i]}
    if not r.get('ID_Flux'): continue
    # Règle de calcul : seuls les éléments opérationnels du suivi réel
    # (demandes AVRO et Configuration) alimentent les indicateurs.
    # Le catalogue sert uniquement à enrichir Domaine/Sous_Domaine et ne
    # doit jamais augmenter les volumes du dashboard.
    if r.get('Type_Livraison') not in {'AVRO', 'Configuration', 'Anomalie'}: continue
    source = str(r.get('Source') or '').lower()
    if r.get('Type_Livraison') != 'Anomalie' and 'suivi' not in source: continue
    def v(k,d=''):
        x=r.get(k,d)
        return x.isoformat() if isinstance(x,(date,datetime)) else (x if x is not None else d)
    records.append(dict(semaine=v('Semaine'),date=v('Date_Rapport'),id=v('ID_Flux'),domaine=v('Domaine','Non classé'),sousDomaine=v('Sous_Domaine','Non classé'),environnement=v('Environnement'),type=v('Type_Livraison'),statut=v('Statut'),version=v('Version'),nombre=float(v('Nombre',0) or 0),commentaire=v('Commentaire'),nature=v('Nature_Donnée'),source=v('Source'),reference=v('Référence_Source'),sprint=v('Sprint','Sprint non défini'),niveauSemaine=v('Niveau_Semaine'),etatFlux=v('État_Flux'),etatAnomalie=v('État_Anomalie')))
records=list({(r['semaine'],r['id'],r['domaine'],r['sousDomaine'],r['environnement'],r['type']):r for r in records}.values())
if not records:
    raise SystemExit("Aucune donnée exploitable dans Reporting / Reporting N-1. Vérifiez les colonnes ID_Flux, Type_Livraison, Source, SIT/UAT.")
_weeks=sorted({r['semaine'] for r in records})
for r in records:
    r['sprint']='Sprint 21' if r['semaine']==_weeks[-1] else 'Sprint 20'
    r['niveauSemaine']='Sprint actuel' if r['semaine']==_weeks[-1] else 'Sprint N-1'
payload={'generatedAt':datetime.now().isoformat(timespec='seconds'),'workbook':XLSX.name,'records':records}
(ROOT/'dashboard_gil_data.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8')

HTML='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard GIL</title>
<style>:root{--n:#17324d;--b:#2878b5;--g:#16a264;--r:#cc3b3b;--a:#e89a18;--m:#667589;--l:#dce4ea}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:#182331;font-family:Segoe UI,Arial}.top{background:linear-gradient(120deg,var(--n),#27638e);color:white;padding:22px}.topin,main{max-width:1400px;margin:auto}.top h1{margin:0}.top p{margin:5px 0 0;color:#d9e8f4}.tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}.btn,select{background:#fff;border:1px solid var(--l);padding:10px 13px;border-radius:9px;font-weight:650}.btn{cursor:pointer}.btn:disabled{opacity:.4}.crumb{flex:1;color:var(--m);font-size:13px}.pill{background:#e5eef6;padding:8px 12px;border-radius:99px;font-size:12px;font-weight:700}main{padding:0 20px 25px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.panel,.card,.table{background:#fff;border:1px solid var(--l);border-radius:14px;overflow:hidden}.ph{background:var(--n);color:white;padding:12px 16px;font-weight:700}.pb{padding:18px}.head{display:flex;justify-content:space-between;gap:15px}.head h2{margin:0}.head p{color:var(--m);margin:6px 0}.ring{--p:0;width:112px;height:112px;border-radius:50%;background:conic-gradient(var(--g) calc(var(--p)*1%),#e7edf1 0);display:grid;place-items:center;position:relative}.ring:after{content:'';position:absolute;inset:13px;background:white;border-radius:50%}.ring b{position:relative;z-index:1;font-size:25px}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-top:18px}.kpi{border:1px solid var(--l);border-radius:10px;padding:11px}.kpi span{display:block;color:var(--m);font-size:10px;text-transform:uppercase;font-weight:700}.kpi b{font-size:23px}.green{color:var(--g)}.red{color:var(--r)}.amber{color:var(--a)}.bars{display:grid;gap:15px}.bar{display:grid;grid-template-columns:90px 1fr 35px;gap:8px;align-items:center;font-size:12px}.track,.prog{height:10px;background:#edf1f4;border-radius:99px;overflow:hidden}.fill{height:100%;border-radius:99px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.card{padding:16px;cursor:pointer;transition:.15s}.card:hover{transform:translateY(-2px);box-shadow:0 8px 22px #17324d1a}.card h3{margin:0}.sub{color:var(--m);font-size:12px;margin:5px 0 12px}.mini{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.mini div{text-align:center;background:#f3f6f8;padding:8px;border-radius:8px}.mini b{display:block;font-size:18px}.mini span{font-size:9px;color:var(--m)}.prog{height:7px;margin-top:12px}.prog div{height:100%;background:var(--g)}h2.sec{font-size:18px;margin:23px 0 12px}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:1050px}th{background:var(--n);color:white;text-align:left;padding:11px;font-size:12px}td{padding:10px;border-bottom:1px solid #e9eef1;font-size:12px;vertical-align:top}.badge{padding:4px 8px;border-radius:99px;font-weight:700}.bok{background:#dff5e9;color:var(--g)}.bko{background:#fde4e4;color:var(--r)}.bpr{background:#fff1cc;color:#965d00}.foot{text-align:center;color:var(--m);font-size:11px;margin-top:22px}@media(max-width:850px){.hero{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:520px){.kpis{grid-template-columns:repeat(2,1fr)}.head{display:block}.ring{margin-top:12px}}</style></head>
<body><header class="top"><div class="topin"><h1>Dashboard GIL</h1><p>Calculs basés sur le suivi réel des demandes AVRO et Configuration</p></div></header><main><div class="tools"><button class="btn" id="back">← Retour à la page précédente</button><select id="sprint"></select><div class="crumb" id="crumb"></div><div class="pill" id="nature"></div></div><div id="app"></div><div class="foot" id="foot"></div></main>
<script>const D=__DATA__,S={sprint:'',week:null,domain:null,sub:null,stack:[]},app=document.querySelector('#app'),back=document.querySelector('#back'),sel=document.querySelector('#sprint');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uniq=a=>[...new Set(a.filter(Boolean))],sum=(a,f)=>a.reduce((n,r)=>n+(f?f(r):+r.nombre),0),grp=(a,k)=>Object.entries(a.reduce((o,r)=>((o[r[k]]??=[]).push(r),o),{})).sort((x,y)=>x[0].localeCompare(y[0],'fr'));
function met(a){let weeks=uniq(a.map(r=>r.semaine)).sort();if(weeks.length>1){let latest=weeks.at(-1);a=a.filter(r=>r.semaine===latest)}let total=sum(a),ready=sum(a,r=>r.etatFlux==='Prêt'?+r.nombre:0),ok=sum(a,r=>r.etatAnomalie==='OK'?+r.nombre:0),ko=sum(a,r=>r.etatAnomalie==='KO'?+r.nombre:0),progress=sum(a,r=>r.etatFlux==='En cours'?+r.nombre:0),anomaly=sum(a,r=>r.etatAnomalie!=='OK'?+r.nombre:0);return{total,ready,ok,ko,progress,anomaly,rate:total?Math.round(ready*100/total):0}}
const KP=m=>`<div class=kpis>${[['Total flux',m.total,''],['Prêts',m.ready,'green'],['Anomalies ouvertes',m.anomaly,'red'],['OK',m.ok,'green'],['KO',m.ko,'red'],['En cours',m.progress,'amber']].map(x=>`<div class=kpi><span>${x[0]}</span><b class=${x[2]}>${x[1]}</b></div>`).join('')}</div>`;
function hero(t,s,a){let m=met(a),mx=Math.max(m.total,1);return `<div class=hero><section class=panel><div class=ph>Synthèse</div><div class=pb><div class=head><div><h2>${esc(t)}</h2><p>${esc(s)}</p></div><div class=ring style="--p:${m.rate}"><b>${m.rate}%</b></div></div>${KP(m)}</div></section><section class=panel><div class=ph>Graphiques recalculés automatiquement</div><div class="pb bars">${[['Prêts',m.ready,'var(--g)'],['KO',m.ko,'var(--r)'],['En cours',m.progress,'var(--a)']].map(x=>`<div class=bar><b>${x[0]}</b><div class=track><div class=fill style="width:${x[1]*100/mx}%;background:${x[2]}"></div></div><b>${x[1]}</b></div>`).join('')}</div></section></div>`}
function card(n,a,k){let m=met(a);return `<article class=card data-id="${esc(n)}"><h3>${esc(n)}</h3><div class=sub>${k} · ${esc(uniq(a.map(x=>x.nature)).join(' + '))}</div><div class=mini><div><b>${m.total}</b><span>Total</span></div><div><b class=green>${m.ready}</b><span>Prêts</span></div><div><b class=red>${m.ko}</b><span>KO</span></div><div><b class=amber>${m.progress}</b><span>En cours</span></div></div><div class=prog><div style="width:${m.rate}%"></div></div></article>`}
function nav(o){S.stack.push({week:S.week,domain:S.domain,sub:S.sub});Object.assign(S,o);render()}function bind(o){app.querySelectorAll('.card').forEach(c=>c.onclick=()=>nav({[o]:c.dataset.id}))}
function render(){let rows=D.records.filter(r=>r.sprint===S.sprint),f=S.week?rows.filter(r=>r.semaine===S.week):rows;if(S.domain)f=f.filter(r=>r.domaine===S.domain);if(S.sub)f=f.filter(r=>r.sousDomaine===S.sub);back.disabled=!S.stack.length;document.querySelector('#crumb').textContent=[S.sprint,S.week,S.domain,S.sub].filter(Boolean).join(' › ');document.querySelector('#nature').textContent=uniq(f.map(r=>r.nature)).join(' + ')||'Données';if(S.sub){app.innerHTML=hero(S.sub,`${S.week} · ${S.domain} — détail des flux et anomalies`,f)+`<h2 class=sec>Détail des flux</h2><div class=table><table><thead><tr><th>ID flux</th><th>Env.</th><th>Type</th><th>Version</th><th>Nombre</th><th>État</th><th>Statut source</th><th>Commentaire</th><th>Source</th></tr></thead><tbody>${f.map(r=>`<tr><td><b>${esc(r.id)}</b></td><td>${esc(r.environnement)}</td><td>${esc(r.type)}</td><td>${esc(r.version)}</td><td>${r.nombre}</td><td>${r.etatAnomalie==='KO'?'<span class="badge bko">KO</span>':r.etatFlux==='En cours'?'<span class="badge bpr">En cours</span>':'<span class="badge bok">OK / Prêt</span>'}</td><td>${esc(r.statut)}</td><td>${esc(r.commentaire)}</td><td>${esc(r.source)} ${esc(r.reference)}</td></tr>`).join('')}</tbody></table></div>`}else if(S.domain){app.innerHTML=hero(S.domain,`${S.week} — sélectionnez un sous-domaine`,f)+`<h2 class=sec>Sous-domaines</h2><div class=cards>${grp(f,'sousDomaine').map(([n,a])=>card(n,a,'Sous-domaine')).join('')}</div>`;bind('sub')}else if(S.week){app.innerHTML=hero(`${S.week} — ${f[0]?.niveauSemaine||''}`,'Vue hebdomadaire — sélectionnez un domaine',f)+`<h2 class=sec>Domaines</h2><div class=cards>${grp(f,'domaine').map(([n,a])=>card(n,a,'Domaine')).join('')}</div>`;bind('domain')}else{app.innerHTML=hero(S.sprint,'Vue globale du sprint — sélectionnez une semaine',f)+`<h2 class=sec>Avancement des semaines</h2><div class=cards>${grp(f,'semaine').map(([n,a])=>card(`${a[0].niveauSemaine||n} — ${n}`,a,'Avancement hebdomadaire').replace(`data-id="${a[0].niveauSemaine||n} — ${n}"`,`data-id="${n}"`)).join('')}</div>`;bind('week')}}
back.onclick=()=>{if(S.stack.length)Object.assign(S,S.stack.pop());render()};let sp=uniq(D.records.map(r=>r.sprint));sel.innerHTML=sp.map(x=>`<option>${esc(x)}</option>`).join('');S.sprint=sp.at(-1)||'';sel.value=S.sprint;sel.onchange=()=>{S.sprint=sel.value;S.week=S.domain=S.sub=null;S.stack=[];render()};document.querySelector('#foot').textContent=`Source de calcul : Reporting (${D.workbook}), demandes AVRO et Configuration uniquement — généré le ${new Date(D.generatedAt).toLocaleString('fr-FR')}. Modifiez uniquement la feuille Reporting avant l’actualisation.`;render();</script></body></html>'''
ADDON_CSS='''.health-label{text-align:center;font-size:22px;font-weight:800;margin-top:7px}.trend{width:100%;height:260px;display:block}.auto-block{margin-top:16px}.auto-block table{min-width:800px}.empty{padding:20px;text-align:center;color:var(--m)}'''
ADDON_JS=r'''
function healthInfo(m){return m.rate>=80?{label:'Vert',color:'#16a264'}:m.rate>=60?{label:'Orange',color:'#e89a18'}:{label:'Rouge',color:'#cc3b3b'}}
function priorityBlocks(current,all){let m=met(current),h=healthInfo(m),risk=m.ko+m.progress,bad=current.filter(r=>r.etatAnomalie==='KO'||r.etatFlux==='En cours');return `<section class="panel auto-block"><div class=ph>Évolution hebdomadaire</div><div class=pb><canvas class=trend id=trend></canvas></div></section><section class="panel auto-block"><div class=ph>Décision / interprétation / priorisation</div><div class=table><table><thead><tr><th>Décision</th><th>Interprétation</th><th>Priorisation</th><th>Action</th></tr></thead><tbody><tr><td>Santé de la période</td><td>État <b style="color:${h.color}">${h.label}</b> — ${m.rate}% de flux prêts</td><td>${risk?'P1':'P2'}</td><td>${risk?`${risk} élément(s) à analyser ou traiter`:'Aucune action bloquante'}</td></tr><tr><td>Flux prêts</td><td>${m.ready} prêts sur ${m.total}</td><td>${m.ready===m.total?'P2':'P1'}</td><td>${m.ready===m.total?'Maintenir le suivi':'Traiter en priorité les KO et en cours'}</td></tr></tbody></table></div></section><section class="panel auto-block"><div class=ph>Sujets prioritaires suivis</div><div class=table>${bad.length?`<table><thead><tr><th>Priorité</th><th>Flux</th><th>Domaine</th><th>Sous-domaine</th><th>Environnement</th><th>État</th><th>Action / commentaire</th></tr></thead><tbody>${bad.slice(0,20).map(r=>`<tr><td>${r.etatAnomalie==='KO'?'P0':'P1'}</td><td><b>${esc(r.id)}</b></td><td>${esc(r.domaine)}</td><td>${esc(r.sousDomaine)}</td><td>${esc(r.environnement)}</td><td>${r.etatAnomalie==='KO'?'<span class="badge bko">KO</span>':'<span class="badge bpr">En cours</span>'}</td><td>${esc(r.commentaire||'Qualification et traitement à planifier')}</td></tr>`).join('')}</tbody></table>`:'<div class=empty>Aucun sujet prioritaire ouvert sur cette vue.</div>'}</div></section>`}
function drawTrend(rows){let c=document.querySelector('#trend');if(!c)return;let sets=grp(rows,'semaine').map(([w,a])=>({w,m:met(a)})),d=devicePixelRatio||1,W=c.clientWidth,H=c.clientHeight;c.width=W*d;c.height=H*d;let x=c.getContext('2d');x.scale(d,d);x.font='12px Segoe UI';let p={l:45,r:20,t:18,b:45},iw=W-p.l-p.r,ih=H-p.t-p.b,max=Math.max(1,...sets.map(s=>s.m.total));x.strokeStyle='#dce4ea';x.fillStyle='#667589';for(let i=0;i<5;i++){let y=p.t+ih*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(W-p.r,y);x.stroke();x.fillText(Math.round(max*(4-i)/4),5,y+4)}[['ready','#2878b5','Prêts'],['ko','#cc3b3b','KO'],['progress','#e89a18','En cours']].forEach(([k,col,label],si)=>{x.strokeStyle=col;x.fillStyle=col;x.lineWidth=3;x.beginPath();sets.forEach((s,i)=>{let px=p.l+(sets.length===1?iw/2:iw*i/(sets.length-1)),py=p.t+ih*(1-s.m[k]/max);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();sets.forEach((s,i)=>{let px=p.l+(sets.length===1?iw/2:iw*i/(sets.length-1)),py=p.t+ih*(1-s.m[k]/max);x.beginPath();x.arc(px,py,4,0,Math.PI*2);x.fill()});x.fillRect(p.l+si*105,H-10,10,10);x.fillStyle='#667589';x.fillText(label,p.l+15+si*105,H)});sets.forEach((s,i)=>{let px=p.l+(sets.length===1?iw/2:iw*i/(sets.length-1));x.fillStyle='#667589';x.fillText(s.w,px-24,H-20)})}
const originalRender=render;render=function(){originalRender();let rows=D.records.filter(r=>r.sprint===S.sprint),current=S.week?rows.filter(r=>r.semaine===S.week):rows;if(S.domain)current=current.filter(r=>r.domaine===S.domain);if(S.sub)current=current.filter(r=>r.sousDomaine===S.sub);let ring=document.querySelector('.ring');if(ring){let m=met(current),h=healthInfo(m);ring.style.color=h.color;let label=document.createElement('div');label.className='health-label';label.style.color=h.color;label.textContent=h.label;ring.insertAdjacentElement('afterend',label)}if(!S.domain&&!S.sub){app.insertAdjacentHTML('beforeend',priorityBlocks(current,rows));drawTrend(rows)}};render();
'''
HTML=HTML.replace('</style>',ADDON_CSS+'</style>').replace('</script>',ADDON_JS+'</script>')
if '--data-only' not in sys.argv:
    OUT.write_text(HTML.replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
    print(f'Dashboard généré : {OUT}')
print(f'Données préparées : {len(records)} lignes')
